import React, { useState, useEffect } from 'react';
import { 
  Card, 
  Progress, 
  Tabs, 
  Table, 
  Tag, 
  Button, 
  Modal, 
  InputNumber, 
  Input, 
  message,
  Statistic,
  Row,
  Col,
  Typography,
  Space,
  Tooltip,
  Select
} from 'antd';
import { 
  TrophyOutlined, 
  BulbOutlined, 
  SafetyCertificateOutlined, 
  EditOutlined,
  EyeOutlined,
  BookOutlined
} from '@ant-design/icons';
import axios from 'axios';
import { apiRequest, buildAuthHeaders } from '../api';
import type { ColumnsType } from 'antd/es/table';

const { Title, Text, Paragraph } = Typography;
const { TabPane } = Tabs;
const { TextArea } = Input;
const { Option } = Select;

interface Goal {
  id: string;
  title: string;
  description?: string;
  priority: number;
  status: string;
  created_at: string;
  progress_percentage: number;
  milestones_total: number;
  milestones_completed: number;
  knowledge_quants: number;
}

interface Milestone {
  id: string;
  milestone_title: string;
  milestone_description?: string;
  target_value?: number;
  current_value?: number;
  unit?: string;
  status: string;
  priority: number;
  progress_percentage: number;
  created_at: string;
  updated_at: string;
}

interface Quant {
  id: string;
  title: string;
  content: string;
  category: string;
  priority: number;
  tags: string[];
  energy_weight: number;
  created_at: string;
}

interface Summary {
  total_goals: number;
  total_milestones: number;
  completed_milestones: number;
  in_progress_milestones: number;
  overall_progress: number;
  total_knowledge_quants: number;
  top_goals: Array<{title: string; priority: number}>;
}

const SoulGoals: React.FC = () => {
  const [goals, setGoals] = useState<Goal[]>([]);
  const [milestones, setMilestones] = useState<Milestone[]>([]);
  const [quants, setQuants] = useState<Quant[]>([]);
  const [summary, setSummary] = useState<Summary | null>(null);
  const [selectedGoal, setSelectedGoal] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [updateModalVisible, setUpdateModalVisible] = useState(false);
  const [selectedMilestone, setSelectedMilestone] = useState<Milestone | null>(null);
  const [newValue, setNewValue] = useState<number>(0);
  const [notes, setNotes] = useState<string>('');
  // Для таблицы целей
  const [goalSearch, setGoalSearch] = useState<string>('');
  const [goalStatus, setGoalStatus] = useState<string | undefined>(undefined);
  const [goalPage, setGoalPage] = useState<number>(1);
  const [goalPageSize, setGoalPageSize] = useState<number>(10);

  // Загрузка данных
  const loadGoals = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/api/soul/goals/');
      setGoals(response.data);
    } catch (error) {
      message.error('Ошибка загрузки целей');
    }
    setLoading(false);
  };

  const loadSummary = async () => {
    try {
      const response = await axios.get('/api/soul/goals/summary');
      setSummary(response.data);
    } catch (error) {
      message.error('Ошибка загрузки сводки');
    }
  };

  const loadMilestones = async (goalId: string) => {
    try {
      const response = await axios.get(`/api/soul/goals/${goalId}/milestones`);
      setMilestones(response.data);
    } catch (error) {
      message.error('Ошибка загрузки этапов');
    }
  };

  const loadQuants = async (goalId: string) => {
    try {
      const response = await axios.get(`/api/soul/goals/${goalId}/quants`);
      setQuants(response.data);
    } catch (error) {
      message.error('Ошибка загрузки квантов');
    }
  };

  const updateProgress = async () => {
    if (!selectedMilestone) return;
    
    try {
      await axios.post('/api/soul/goals/progress/update', {
        milestone_id: selectedMilestone.id,
        current_value: newValue,
        notes: notes
      });
      
      message.success('Прогресс обновлен');
      setUpdateModalVisible(false);
      
      // Перезагружаем данные
      if (selectedGoal) {
        loadMilestones(selectedGoal);
      }
      loadGoals();
      loadSummary();
    } catch (error) {
      message.error('Ошибка обновления прогресса');
    }
  };

  useEffect(() => {
    loadGoals();
    loadSummary();
  }, []);

  useEffect(() => {
    if (selectedGoal) {
      loadMilestones(selectedGoal);
      loadQuants(selectedGoal);
    }
  }, [selectedGoal]);

  const getGoalIcon = (title: string) => {
    if (title.includes('Архитектор')) return <TrophyOutlined />;
    if (title.includes('Семь')) return <BulbOutlined />;
    if (title.includes('безопасность')) return <SafetyCertificateOutlined />;
    return <BookOutlined />;
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed': return 'success';
      case 'in_progress': return 'processing';
      case 'pending': return 'default';
      case 'blocked': return 'error';
      default: return 'default';
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case 'completed': return 'Завершено';
      case 'in_progress': return 'В работе';
      case 'pending': return 'Ожидает';
      case 'blocked': return 'Заблокировано';
      default: return status;
    }
  };

  // Фильтрация/сортировка/пагинация целей (клиентская)
  const filteredGoals = goals
    .filter(g => {
      if (goalStatus && g.status !== goalStatus) return false;
      if (goalSearch) {
        const q = goalSearch.toLowerCase();
        return (
          (g.title || '').toLowerCase().includes(q) ||
          (g.description || '').toLowerCase().includes(q)
        );
      }
      return true;
    })
    .sort((a, b) => (b.priority || 0) - (a.priority || 0));

  const pagedGoals = filteredGoals.slice((goalPage - 1) * goalPageSize, goalPage * goalPageSize);

  const goalsColumns: ColumnsType<Goal> = [
    {
      title: 'Цель',
      dataIndex: 'title',
      key: 'title',
      width: 520,
      render: (text: string, record: Goal) => (
        <div>
          <Space>
            {getGoalIcon(record.title)}
            <Text strong style={{ maxWidth: 460, display: 'inline-block' }} ellipsis>
              {record.title}
            </Text>
          </Space>
          {record.description && (
            <div>
              <Text 
                type="secondary" 
                style={{ fontSize: 12, maxWidth: 500, display: 'inline-block', whiteSpace: 'normal', wordBreak: 'break-word' }}
                ellipsis={{ tooltip: record.description }}
              >
                {record.description}
              </Text>
            </div>
          )}
        </div>
      )
    },
    {
      title: 'Прогресс',
      key: 'progress',
      width: 220,
      render: (record: Goal) => (
        <div style={{ minWidth: 180 }}>
          <Progress 
            percent={record.progress_percentage} 
            size="small" 
            status={record.progress_percentage === 100 ? 'success' : 'active'}
          />
          <Text style={{ fontSize: 12 }}>
            {record.milestones_completed}/{record.milestones_total} этапов
          </Text>
        </div>
      )
    },
    {
      title: 'Приоритет',
      dataIndex: 'priority',
      width: 110,
      render: (priority: number) => (
        <Tag color={priority >= 0.9 ? 'red' : priority >= 0.7 ? 'orange' : 'blue'}>
          {priority.toFixed(2)}
        </Tag>
      )
    },
    {
      title: 'Статус',
      dataIndex: 'status',
      width: 140,
      render: (status: string) => (
        <Tag color={getStatusColor(status)}>
          {getStatusText(status)}
        </Tag>
      )
    },
    {
      title: 'Кванты знаний',
      dataIndex: 'knowledge_quants',
      width: 130,
    },
    {
      title: 'Создана',
      dataIndex: 'created_at',
      width: 180,
      render: (t: string) => new Date(t).toLocaleString()
    },
    {
      title: 'Действия',
      key: 'actions',
      width: 120,
      render: (_: any, record: Goal) => (
        <Button size="small" type="link" onClick={() => setSelectedGoal(record.id)}>
          Детали
        </Button>
      )
    }
  ];

  const milestonesColumns = [
    {
      title: 'Этап',
      dataIndex: 'milestone_title',
      key: 'title',
      render: (text: string, record: Milestone) => (
        <div>
          <Text strong>{text}</Text>
          {record.milestone_description && (
            <div>
              <Text type="secondary" style={{ fontSize: '12px' }}>
                {record.milestone_description}
              </Text>
            </div>
          )}
        </div>
      ),
    },
    {
      title: 'Прогресс',
      key: 'progress',
      render: (record: Milestone) => (
        <div>
          <Progress 
            percent={record.progress_percentage} 
            size="small" 
            status={record.status === 'completed' ? 'success' : 'active'}
          />
          <Text style={{ fontSize: '12px' }}>
            {record.current_value || 0} / {record.target_value || 0} {record.unit || ''}
          </Text>
        </div>
      ),
    },
    {
      title: 'Статус',
      dataIndex: 'status',
      key: 'status',
      render: (status: string) => (
        <Tag color={getStatusColor(status)}>
          {getStatusText(status)}
        </Tag>
      ),
    },
    {
      title: 'Приоритет',
      dataIndex: 'priority',
      key: 'priority',
      render: (priority: number) => (
        <Tag color={priority >= 0.9 ? 'red' : priority >= 0.7 ? 'orange' : 'blue'}>
          {priority.toFixed(2)}
        </Tag>
      ),
    },
    {
      title: 'Действия',
      key: 'actions',
      render: (record: Milestone) => (
        <Button
          type="primary"
          size="small"
          icon={<EditOutlined />}
          onClick={() => {
            setSelectedMilestone(record);
            setNewValue(record.current_value || 0);
            setNotes('');
            setUpdateModalVisible(true);
          }}
        >
          Обновить
        </Button>
      ),
    },
  ];

  const quantsColumns = [
    {
      title: 'Квант знаний',
      dataIndex: 'title',
      key: 'title',
      render: (text: string, record: Quant) => (
        <div>
          <Text strong>{text}</Text>
          <div>
            <Space>
              <Tag>{record.category}</Tag>
              <Text type="secondary">Вес: {record.energy_weight}</Text>
            </Space>
          </div>
        </div>
      ),
    },
    {
      title: 'Содержание',
      dataIndex: 'content',
      key: 'content',
      render: (content: string) => (
        <Tooltip title={content}>
          <Text ellipsis style={{ maxWidth: 300 }}>
            {content.length > 100 ? `${content.substring(0, 100)}...` : content}
          </Text>
        </Tooltip>
      ),
    },
    {
      title: 'Теги',
      dataIndex: 'tags',
      key: 'tags',
      render: (tags: string[]) => (
        <Space>
          {tags.map(tag => (
            <Tag key={tag} size="small">{tag}</Tag>
          ))}
        </Space>
      ),
    },
  ];

  return (
    <div style={{ padding: '24px' }}>
      <Title level={2}>
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}>
          <img src="/android-chrome-192x192.png" alt="Soul" style={{ width: 28, height: 28, borderRadius: 6 }} />
          Цели и Прогресс Соул
        </span>
      </Title>
      
      {/* Сводка */}
      {summary && (
        <Row gutter={16} style={{ marginBottom: 24 }}>
          <Col span={6}>
            <Card>
              <Statistic
                title="Всего целей"
                value={summary.total_goals}
                prefix={<TrophyOutlined />}
              />
            </Card>
          </Col>
          <Col span={6}>
            <Card>
              <Statistic
                title="Общий прогресс"
                value={summary.overall_progress}
                suffix="%"
                precision={1}
              />
            </Card>
          </Col>
          <Col span={6}>
            <Card>
              <Statistic
                title="Завершено этапов"
                value={summary.completed_milestones}
                suffix={`/ ${summary.total_milestones}`}
              />
            </Card>
          </Col>
          <Col span={6}>
            <Card>
              <Statistic
                title="Квантов знаний"
                value={summary.total_knowledge_quants}
                prefix={<BookOutlined />}
              />
            </Card>
          </Col>
        </Row>
      )}

      {/* Таблица целей (как на странице Квантов) */}
      <Card style={{ marginTop: 12 }}>
        <Space style={{ marginBottom: 12 }} wrap>
          <Input.Search
            allowClear
            placeholder="Поиск по названию/описанию цели"
            onSearch={(v) => { setGoalPage(1); setGoalSearch(v.trim()); }}
            style={{ width: 360 }}
          />
          <Select
            allowClear
            placeholder="Статус"
            value={goalStatus}
            onChange={(v) => { setGoalPage(1); setGoalStatus(v || undefined); }}
            style={{ width: 180 }}
          >
            <Option value="active">В работе</Option>
            <Option value="completed">Завершено</Option>
            <Option value="pending">Ожидает</Option>
            <Option value="blocked">Заблокировано</Option>
          </Select>
          <Button onClick={() => { setGoalSearch(''); setGoalStatus(undefined); setGoalPage(1); }}>Сброс</Button>
        </Space>

        <Table
          rowKey="id"
          loading={loading}
          dataSource={pagedGoals}
          columns={goalsColumns}
          scroll={{ x: 1180 }}
          pagination={{
            current: goalPage,
            pageSize: goalPageSize,
            total: filteredGoals.length,
            onChange: (p, ps) => { setGoalPage(p); setGoalPageSize(ps); },
            showSizeChanger: true,
            pageSizeOptions: [10, 20, 50, 100]
          }}
          onRow={(record) => ({
            onClick: () => setSelectedGoal(record.id)
          })}
        />
      </Card>

      {/* Детали выбранной цели */}
      {selectedGoal && (
        <Card 
          title={`Детали цели: ${goals.find(g => g.id === selectedGoal)?.title}`}
          style={{ marginTop: 24 }}
        >
          <Tabs defaultActiveKey="milestones">
            <TabPane tab="Этапы прогресса" key="milestones">
              <Table
                columns={milestonesColumns}
                dataSource={milestones}
                rowKey="id"
                pagination={false}
                size="small"
              />
            </TabPane>
            
            <TabPane tab="Кванты знаний" key="quants">
              <Table
                columns={quantsColumns}
                dataSource={quants}
                rowKey="id"
                pagination={false}
                size="small"
              />
            </TabPane>
          </Tabs>
        </Card>
      )}

      {/* Модал обновления прогресса */}
      <Modal
        title="Обновить прогресс"
        visible={updateModalVisible}
        onOk={updateProgress}
        onCancel={() => setUpdateModalVisible(false)}
        okText="Сохранить"
        cancelText="Отмена"
      >
        {selectedMilestone && (
          <div>
            <Title level={4}>{selectedMilestone.milestone_title}</Title>
            
            <div style={{ marginBottom: 16 }}>
              <Text>Текущее значение:</Text>
              <InputNumber
                value={newValue}
                onChange={(value) => setNewValue(value || 0)}
                style={{ width: '100%', marginTop: 8 }}
                max={selectedMilestone.target_value}
                min={0}
                step={0.1}
              />
              <Text type="secondary">
                Цель: {selectedMilestone.target_value} {selectedMilestone.unit}
              </Text>
            </div>
            
            <div>
              <Text>Заметки (опционально):</Text>
              <TextArea
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                rows={3}
                placeholder="Добавьте заметки о прогрессе..."
                style={{ marginTop: 8 }}
              />
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default SoulGoals;
